import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { brand, packageRoot } from '../lib/brand.js';
import { elements } from '../convert/color.js';
import { semanticClass } from '../convert/kinds.js';
import { SCOPE, themeDeclarations } from './theme.js';
// The stylesheets init writes beyond build/: brand.css placed where the app serves it (its font URLs fitted), kinds.css
// (the library's look by kind as plain classes, for apps without Tailwind, compiled from the same recipes with
// Tailwind's compiler), the Tailwind 3 preset, and the lines that wire them into a stylesheet, a script or a layout.
const build = (f) => readFileSync(join(packageRoot, 'build', f), 'utf8');
/** brand.css with its font URLs pointing where the fonts are: beside it (`./fonts/`), or under the app's static URL. */
export function brandCss(file, fonts) {
    const base = brand().assetBase.replace(/\/$/, '');
    const text = build(file);
    const to = fonts === 'relative' ? './' : `${fonts}${base}/`;
    return text.replaceAll(`url("${base}/`, `url("${to}`);
}
/** Every class a kind's recipe uses, for the Tailwind 3 preset check and kinds.css. */
export function recipeClasses() {
    const out = new Set();
    for (const def of Object.values(elements().kinds)) {
        for (const s of [def.base, def.icon, def.backdrop, def.th?.base, def.td?.base, def.tab?.base, ...Object.values(def.variants ?? {})])
            for (const c of String(s ?? '').split(/\s+/))
                if (c)
                    out.add(c);
    }
    return [...out];
}
/** A recipe as it reads on any element: `hover:enabled:` (a button's) also covers links, as `hover:not-disabled:`. */
const forAny = (list) => list.replace(/(^|\s)(hover|active):enabled:/g, '$1$2:not-disabled:').trim();
/** kinds.css: `.ds-button`, `.ds-button-secondary`, `.ds-table-th`... with the library's look, as plain CSS. */
export async function kindsCss() {
    const { compile } = await import('tailwindcss');
    const req = createRequire(join(packageRoot, 'package.json'));
    const twDir = dirname(req.resolve('tailwindcss/package.json'));
    const rules = [];
    const rule = (selector, list) => {
        if (list?.trim())
            rules.push(`${selector} { @apply ${forAny(list)}; }`);
    };
    // What the recipe replaces and does not set itself is cleared, as Tailwind's restyle drops those classes: an app's
    // own padding and shadow on .btn would otherwise survive under the library's look.
    // Form controls take no font from the page without Tailwind's preflight: the recipe's type comes with the text face.
    const resets = (replace = [], list = '') => [replace.includes('padding') ? 'p-0' : '', replace.includes('shadow') ? 'shadow-none' : '', replace.includes('bg') && !/(^|\s)bg-/.test(list) ? 'bg-transparent' : '', replace.includes('type') && !/(^|\s)(type-|font-(text|heading|code|brand))/.test(list) ? 'font-text' : '', list].filter(Boolean).join(' ');
    // Three classes deep: above an app's own class (.btn) and above a component's scoped one too (Angular's
    // .save[_ngcontent-x], Vue's .save[data-v-x], Svelte's .save.svelte-x), which loads after kinds.css and would win a tie.
    const x3 = (c) => `.${c}.${c}.${c}`;
    for (const [kind, def] of Object.entries(elements().kinds)) {
        const k = semanticClass(kind);
        rule(x3(k), def.base ? resets(def.replace, def.base) : '');
        for (const [v, list] of Object.entries(def.variants ?? {}))
            rule(`.${k}.${k}.${semanticClass(kind, v)}`, list);
        if (def.icon)
            rule(`.${k}.${k}.${semanticClass(kind, 'icon')}`, def.icon);
        for (const part of ['th', 'td', 'tab'])
            if (def[part])
                rule(x3(semanticClass(kind, part)), resets(def[part].replace, def[part].base));
        if (def.backdrop)
            rule(x3(semanticClass(kind, 'backdrop')), def.backdrop);
    }
    rule(`a${x3(semanticClass('button'))}`, 'inline-flex items-center justify-center no-underline');
    for (const name of Object.keys(elements().text.headings))
        rule(x3(`ds-type-${name}`), `type-${name}`);
    const input = `@import "tailwindcss/theme.css" theme(inline);\n${build('theme.css')}\n${rules.join('\n')}\n`;
    const compiler = await compile(input, {
        base: packageRoot,
        loadStylesheet: async (id) => {
            const path = id === 'tailwindcss/theme.css' || id === 'tailwindcss/theme' ? join(twDir, 'theme.css') : id;
            return { path, base: dirname(path), content: readFileSync(path, 'utf8') };
        },
    });
    const css = compiler.build([]).replace(/^\/\*! tailwindcss[^\n]*\n/, '');
    return `/* ${brand().name} design system: the library's look by kind, as plain classes for apps without Tailwind (apply adds\n   them: ds-button, ds-button-secondary, ds-input, ds-card...). Generated by ${brand().bin} from brand/; do not edit. */\n${css}`;
}
// ---- Tailwind 3: the theme as a preset (utilities read the brand's variables). ----
const TW3_DEFAULTS = {
    'fontFamily.sans': 'ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"',
    'fontFamily.mono': 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace',
    'letterSpacing.tight': '-0.025em',
    'transitionTimingFunction.out': 'cubic-bezier(0, 0, 0.2, 1)',
};
/** The Tailwind 3 preset and, for keys Tailwind already has, the CSS that scopes them (like the Tailwind 4 theme). */
export function tailwind3Preset(whole) {
    const theme = build('theme.css');
    const decls = themeDeclarations(theme);
    const t = { colors: {}, fontFamily: {}, fontWeight: {}, fontSize: {}, letterSpacing: {}, borderRadius: {}, spacing: {}, maxWidth: {}, transitionTimingFunction: {}, transitionDuration: {} };
    const scoped = [];
    const app = [];
    const lib = [];
    const set = (group, key, value) => {
        const own = TW3_DEFAULTS[`${group}.${key}`];
        if (own !== undefined && !whole && typeof value === 'string') {
            const name = `--ds-scope-${group}-${key}`;
            scoped.push(`${group}.${key}`);
            app.push(`  ${name}: ${own};`);
            lib.push(`  ${name}: ${value};`);
            t[group][key] = `var(${name})`;
            return;
        }
        t[group][key] = value;
    };
    for (const [name, value] of decls) {
        const m = name.match(/^--(color|font-weight|font|text|tracking|radius|spacing|container|ease)-(.+)$/);
        if (!m)
            continue;
        const [, kind, key] = m;
        if (kind === 'color')
            set('colors', key, value.startsWith('var(') ? `color-mix(in srgb, ${value} calc(<alpha-value> * 100%), transparent)` : value);
        else if (kind === 'font-weight')
            set('fontWeight', key, value);
        else if (kind === 'font')
            set('fontFamily', key, value);
        else if (kind === 'text' && !key.endsWith('--line-height'))
            set('fontSize', key, [value, { lineHeight: decls.get(`--text-${key}--line-height`) ?? 'normal' }]);
        else if (kind === 'tracking')
            set('letterSpacing', key, value);
        else if (kind === 'radius')
            set('borderRadius', key, value);
        else if (kind === 'spacing')
            set('spacing', key, value);
        else if (kind === 'container')
            set('maxWidth', key, value);
        else if (kind === 'ease')
            set('transitionTimingFunction', key, value);
    }
    for (const m of readFileSync(join(packageRoot, 'brand', 'tokens.css'), 'utf8').matchAll(/--ds-duration-[\w-]+\s*:\s*(\d+)ms/g))
        t.transitionDuration[m[1]] = `${m[1]}ms`;
    // Steps the recipes use that Tailwind 3's spacing scale lacks (h-4.5, px-1.25).
    for (const c of recipeClasses()) {
        const n = c.match(/(?:^|:)-?(?:[pm][xytrblse]?|h|w|size|gap(?:-[xy])?|inset(?:-[xy])?|top|left|right|bottom)-(\d+\.\d+|\d+)$/)?.[1];
        if (n && !/^(0|0\.5|1|1\.5|2|2\.5|3|3\.5|4|5|6|7|8|9|10|11|12|14|16|20|24|28|32|36|40|44|48|52|56|60|64|72|80|96)$/.test(n))
            t.spacing[n] = `${Number(n) * 0.25}rem`;
    }
    const utilities = {};
    for (const m of theme.matchAll(/@utility\s+([\w-]+)\s*\{([^}]*)\}/g)) {
        const body = {};
        for (const d of m[2].matchAll(/([\w-]+)\s*:\s*([^;]+);/g))
            body[d[1]] = d[2].trim();
        utilities[`.${m[1]}`] = body;
    }
    const preset = `// ${brand().name} design system: the Tailwind 3 theme (a preset; the values are the brand's CSS variables from brand.css).
// Generated by ${brand().bin}; do not edit.
const plugin = require('tailwindcss/plugin');

module.exports = {
  theme: {
    extend: ${JSON.stringify(t, null, 2).replace(/\n/g, '\n    ')},
  },
  plugins: [
    plugin(({ addUtilities, addVariant }) => {
      addUtilities(${JSON.stringify(utilities, null, 2).replace(/\n/g, '\n      ')});
      addVariant('pointer-coarse', '@media (pointer: coarse)');
      addVariant('pointer-fine', '@media (pointer: fine)');
      addVariant('aria-invalid', '&[aria-invalid="true"]');
      addVariant('not-disabled', '&:not(:disabled)');
    }),
  ],
};
`;
    const scope = scoped.length ? `/* Theme keys Tailwind has too: its own value on the app's pages, the brand's inside the library's components and\n   what a selection restyled. Generated by ${brand().bin}; do not edit. */\n:root {\n${app.join('\n')}\n}\n\n${SCOPE} {\n${lib.join('\n')}\n}\n` : '';
    return { preset, scope };
}
/** A Tailwind 3 config with the preset added (CommonJS or ESM, JS or TS); undefined when it cannot be read safely. */
export function wirePreset(config, spec) {
    if (config.includes(spec))
        return config;
    const esm = /^\s*export\s+default\b/m.test(config) || /^\s*import\s/m.test(config);
    const ref = esm ? '__dsPreset' : `require('${spec}')`;
    let next = config;
    if (/\bpresets\s*:\s*\[/.test(next))
        next = next.replace(/\bpresets\s*:\s*\[/, (m) => `${m}${ref}, `);
    else if (/(module\.exports\s*=\s*\{|export\s+default\s*\{|export\s+default\s+\w+\(\s*\{|satisfies\s+Config\s*=\s*\{|const\s+config(?:\s*:\s*Config)?\s*=\s*\{)/.test(next))
        next = next.replace(/(module\.exports\s*=\s*\{|export\s+default\s*\{|export\s+default\s+\w+\(\s*\{|const\s+config(?:\s*:\s*Config)?\s*=\s*\{)/, (m) => `${m}\n  presets: [${ref}],`);
    else
        return undefined;
    if (esm)
        next = `import __dsPreset from '${spec}';\n${next}`;
    return next;
}
/** A static file's URL as a template writes it: Django's `{% static %}` (STATIC_URL and hashed names follow), else the path. */
export const staticHref = (project, path) => (project.framework === 'django' ? `{% static '${path.replace(/^\//, '')}' %}` : `${project.publicUrl}/${path.replace(/^\//, '')}`);
/** The <link> lines for a layout, in the brand's asset folder under the app's static URL. */
export const linkLines = (project, files) => files.map((f) => `<link rel="stylesheet" href="${staticHref(project, `${brand().assetBase.replace(/^\//, '')}/${f}`)}">`);
/** A layout with the links added before the app's own stylesheets (or before </head>); undefined when there is no head. */
export function insertLinks(layout, lines) {
    // Linked already, in either form (/static/x.css or {% static 'x.css' %}).
    const tail = (l) => l.match(/href="([^"]+)"/)[1].replace(/^\{%\s*static\s+'([^']+)'\s*%\}$/, '$1').replace(/^\/+/, '').replace(/^static\//, '');
    const missing = lines.filter((l) => !layout.includes(tail(l)));
    if (!missing.length)
        return layout;
    // A Django template that uses {% static %} loads its tag library first.
    if (missing.some((l) => l.includes('{% static')) && !/\{%\s*load\s+[^%]*\bstatic\b[^%]*%\}/.test(layout)) {
        const extended = layout.match(/^\s*\{%\s*extends\s[^%]*%\}\s*\n?/);
        layout = extended ? `${extended[0]}{% load static %}\n${layout.slice(extended[0].length)}` : `{% load static %}\n${layout}`;
    }
    const head = layout.search(/<\/head>/i);
    if (head < 0)
        return undefined;
    const before = layout.slice(0, head);
    const anchors = [/<link\b[^>]*rel=["']?stylesheet[^>]*>/i, /<%=\s*stylesheet_link_tag\b/, /@vite\s*\(/, /\{%\s*(?:static|load)\b[^%]*%\}\s*["']?[^"']*\.css/, /<style\b/i];
    let at = head;
    for (const a of anchors) {
        const m = before.match(a);
        if (m?.index !== undefined && m.index < at)
            at = m.index;
    }
    const lineStart = layout.lastIndexOf('\n', at - 1) + 1;
    // Before </head>, the lines take the indent of the head's last line, not of </head> itself.
    const prev = at === head ? layout.slice(0, lineStart).replace(/\s+$/, '').split('\n').pop() ?? '' : '';
    const indent = (at === head && /^[ \t]*</.test(prev) ? prev : layout.slice(lineStart, at)).match(/^[ \t]*/)?.[0] ?? '    ';
    const onOwnLine = /^[ \t]*$/.test(layout.slice(lineStart, at));
    const block = missing.map((l) => `${indent}${l}\n`).join('');
    return onOwnLine ? `${layout.slice(0, lineStart)}${block}${layout.slice(lineStart)}` : `${layout.slice(0, at)}${missing.join('')}${layout.slice(at)}`;
}
/** A script (layout.tsx, main.ts, an Astro frontmatter) with side-effect CSS imports added after its imports. */
export function insertImports(code, specs) {
    const missing = specs.filter((s) => !code.includes(`'${s}'`) && !code.includes(`"${s}"`));
    if (!missing.length)
        return code;
    const lines = missing.map((s) => `import '${s}';`).join('\n');
    // After a 'use client' directive and the last import; at the top otherwise.
    const imports = [...code.matchAll(/^import\s[^;]*?(?:from\s*)?['"][^'"]+['"];?[ \t]*$/gm)];
    const last = imports[imports.length - 1];
    if (last?.index !== undefined) {
        const end = last.index + last[0].length;
        return `${code.slice(0, end)}\n${lines}${code.slice(end)}`;
    }
    const directive = code.match(/^(['"])use (client|server)\1;?\s*\n/);
    if (directive)
        return `${directive[0]}${lines}\n${code.slice(directive[0].length)}`;
    return `${lines}\n${code}`;
}
